// Datos reales de Recepción Post-Venta & Retornos SATI - NISSEI Sucursal Ciudad del Este
export interface RecepcionTicket {
  idOrden: string;
  codigoProducto: string;
  cliente: string;
  mensaje: string;
  fechaIngreso: string;
  fechaEntregada?: string;
  fechaVenta?: string;
  estado: string; // "Entregada" | "En Reparación" | "QC" | "Reparada" | "Asignada" | "En Asignacion" | etc.
  tipoComponente: string;
  marca: string;
  modelo: string;
  serial: string;
  accesorios?: string;
  esNuevoIngreso?: boolean;
  esEstadoCambiadoReciente?: boolean;
  esEntregadoReciente?: boolean;
  // Cruce de datos con Casa Matriz CDE
  idOrdenCde?: string;
  estadoCde?: string;
  fechaDespachoCde?: string;
  fechaIngresoCde?: string;
  recibidoEnDeposito?: boolean;
  fechaRecibidoDeposito?: string;
  enCamino?: boolean;
  ingresadoEnCde?: boolean;
}

