export const STORAGE_KEY = 'nissei_recepcion_tickets_v1';

export function getStoredTickets(): RecepcionTicket[] {
  if (typeof window === 'undefined') return INITIAL_RECEPCION_DATA;
  try {
    const raw = localStorage.getItem(STORAGE_KEY);
    if (!raw) {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(INITIAL_RECEPCION_DATA));
      return INITIAL_RECEPCION_DATA;
    }
    const parsed = JSON.parse(raw);
    if (Array.isArray(parsed) && parsed.length > 0) {
      return parsed;
    }
    return INITIAL_RECEPCION_DATA;
  } catch (e) {
    console.error('Error cargando tickets de localStorage:', e);
    return INITIAL_RECEPCION_DATA;
  }
}

export function saveTickets(tickets: RecepcionTicket[]) {
  if (typeof window === 'undefined') return;
  try {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(tickets));
  } catch (e) {
    console.error('Error guardando tickets en localStorage:', e);
  }
}

const NEW_INGRESOS_STORAGE_KEY = 'nissei_recepcion_nuevos_ingresos_ids';
const ESTADOS_CAMBIADOS_STORAGE_KEY = 'nissei_recepcion_estados_cambiados_ids';
const ENTREGADOS_RECIENTES_STORAGE_KEY = 'nissei_recepcion_entregados_recientes_ids';

const INITIAL_STATUS_MAP = new Map<string, string>(
  INITIAL_RECEPCION_DATA.map((t) => [
    String(t.idOrden).trim(),
    (t.estado || '').trim().toLowerCase(),
  ])
);

function getStoredIds(key: string): string[] {
  if (typeof window === 'undefined') return [];
  try {
    const raw = localStorage.getItem(key);
    if (!raw) return [];
    const parsed = JSON.parse(raw);
    return Array.isArray(parsed) ? parsed.map(String) : [];
  } catch {
    return [];
  }
}

function recordStoredId(key: string, idOrden: string): void {
  if (typeof window === 'undefined') return;
  try {
    const current = getStoredIds(key);
    const cleanId = String(idOrden).trim();
    if (!current.includes(cleanId)) {
      localStorage.setItem(key, JSON.stringify([cleanId, ...current]));
    }
  } catch {
    // ignore storage errors
  }
}

export function getNuevoIngresoIds(): string[] {
  return getStoredIds(NEW_INGRESOS_STORAGE_KEY);
}

export function isTicketNuevoIngreso(ticket: RecepcionTicket): boolean {
  const cleanId = String(ticket.idOrden).trim();
  if (ticket.esNuevoIngreso) return true;
  if ((ticket.mensaje || '').includes('Accesorios:')) return true;
  if (!INITIAL_STATUS_MAP.has(cleanId)) return true;
  return getStoredIds(NEW_INGRESOS_STORAGE_KEY).includes(cleanId);
}

export function isTicketEstadoCambiadoReciente(ticket: RecepcionTicket): boolean {
  const cleanId = String(ticket.idOrden).trim();
  if (ticket.esEstadoCambiadoReciente) return true;
  if (getStoredIds(ESTADOS_CAMBIADOS_STORAGE_KEY).includes(cleanId)) return true;
  const initialStatus = INITIAL_STATUS_MAP.get(cleanId);
  if (initialStatus !== undefined) {
    return initialStatus !== (ticket.estado || '').trim().toLowerCase();
  }
  return false;
}

export function isTicketEntregadoReciente(ticket: RecepcionTicket): boolean {
  const cleanId = String(ticket.idOrden).trim();
  const currentEst = (ticket.estado || '').trim().toLowerCase();
  if (currentEst !== 'entregada') return false;

  if (ticket.esEntregadoReciente) return true;
  if (getStoredIds(ENTREGADOS_RECIENTES_STORAGE_KEY).includes(cleanId)) return true;

  const initialStatus = INITIAL_STATUS_MAP.get(cleanId);
  if (initialStatus === undefined) return true;
  return initialStatus !== 'entregada';
}

export function applyCloudRecepcionTickets(rawData: RecepcionTicket[]): RecepcionTicket[] {
  const localNewIds = new Set(getStoredIds(NEW_INGRESOS_STORAGE_KEY));
  const localChangedIds = new Set(getStoredIds(ESTADOS_CAMBIADOS_STORAGE_KEY));
  const localDeliveredIds = new Set(getStoredIds(ENTREGADOS_RECIENTES_STORAGE_KEY));

  const enriched: RecepcionTicket[] = rawData.map((t: RecepcionTicket) => {
    const cleanId = String(t.idOrden).trim();
    const estLow = (t.estado || '').trim().toLowerCase();
    const initialEst = INITIAL_STATUS_MAP.get(cleanId);
    return {
      ...t,
      esNuevoIngreso:
        Boolean(t.esNuevoIngreso) ||
        localNewIds.has(cleanId) ||
        !INITIAL_STATUS_MAP.has(cleanId) ||
        (t.mensaje || '').includes('Accesorios:'),
      esEstadoCambiadoReciente:
        Boolean(t.esEstadoCambiadoReciente) ||
        localChangedIds.has(cleanId) ||
        (initialEst !== undefined && initialEst !== estLow),
      esEntregadoReciente:
        estLow === 'entregada' &&
        (Boolean(t.esEntregadoReciente) ||
          localDeliveredIds.has(cleanId) ||
          initialEst === undefined ||
          initialEst !== 'entregada'),
    };
  });
  saveTickets(enriched);
  return enriched;
}

export async function fetchTicketsFromMySQL(options?: {
  throwOnError?: boolean;
}): Promise<RecepcionTicket[]> {
  try {
    const res = await fetch('/api/db?module=recepcion', { cache: 'no-store' });
    const json = await res.json().catch(() => null);
    if (!res.ok || !json?.ok) {
      throw new Error(json?.error || `Error MySQL (HTTP ${res.status})`);
    }
    if (Array.isArray(json.data) && json.data.length > 0) {
      return applyCloudRecepcionTickets(json.data as RecepcionTicket[]);
    }
  } catch (err) {
    console.warn('[MySQL Sync Recepcion] Usando caché local:', err);
    if (options?.throwOnError) {
      throw err instanceof Error ? err : new Error('Error al conectar con MySQL.');
    }
  }
  return getStoredTickets();
}

export async function addTicketAsync(ticket: RecepcionTicket): Promise<RecepcionTicket[]> {
  const isDelivered = (ticket.estado || '').trim().toLowerCase() === 'entregada';
  const enrichedTicket: RecepcionTicket = {
    ...ticket,
    esNuevoIngreso: true,
    esEntregadoReciente: isDelivered,
  };
  recordStoredId(NEW_INGRESOS_STORAGE_KEY, enrichedTicket.idOrden);
  if (isDelivered) {
    recordStoredId(ENTREGADOS_RECIENTES_STORAGE_KEY, enrichedTicket.idOrden);
  }

  const current = getStoredTickets();
  const exists = current.some((t) => t.idOrden === ticket.idOrden);
  const updated = exists
    ? current.map((t) => (t.idOrden === ticket.idOrden ? enrichedTicket : t))
    : [enrichedTicket, ...current];
  saveTickets(updated);

  if (typeof window !== 'undefined') {
    const res = await fetch('/api/db', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ action: 'ADD_RECEPCION_TICKET', ticket: enrichedTicket }),
    });
    const json = await res.json().catch(() => null);
    if (!res.ok || !json?.ok) {
      throw new Error(json?.error || 'No se pudo guardar el ticket en MySQL.');
    }
    if (Array.isArray(json.data) && json.data.length > 0) {
      return applyCloudRecepcionTickets(json.data as RecepcionTicket[]);
    }
  }

  return updated;
}

export function addTicket(ticket: RecepcionTicket): RecepcionTicket[] {
  const isDelivered = (ticket.estado || '').trim().toLowerCase() === 'entregada';
  const enrichedTicket: RecepcionTicket = {
    ...ticket,
    esNuevoIngreso: true,
    esEntregadoReciente: isDelivered,
  };
  recordStoredId(NEW_INGRESOS_STORAGE_KEY, enrichedTicket.idOrden);
  if (isDelivered) {
    recordStoredId(ENTREGADOS_RECIENTES_STORAGE_KEY, enrichedTicket.idOrden);
  }

  const current = getStoredTickets();
  const exists = current.some((t) => t.idOrden === ticket.idOrden);
  const updated = exists
    ? current.map((t) => (t.idOrden === ticket.idOrden ? enrichedTicket : t))
    : [enrichedTicket, ...current];
  saveTickets(updated);

  if (typeof window !== 'undefined') {
    fetch('/api/db', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ action: 'ADD_RECEPCION_TICKET', ticket: enrichedTicket }),
    }).catch((err) => console.error('[MySQL Error Add Ticket]', err));
  }

  return updated;
}

export function updateTicketDetails(
  idOrden: string,
  updates: Partial<RecepcionTicket>
): RecepcionTicket[] {
  const isDelivered = updates.estado?.trim().toLowerCase() === 'entregada';
  if (updates.estado) {
    recordStoredId(ESTADOS_CAMBIADOS_STORAGE_KEY, idOrden);
    if (isDelivered) {
      recordStoredId(ENTREGADOS_RECIENTES_STORAGE_KEY, idOrden);
    }
  }

  const nowDate = new Date().toLocaleDateString('es-PY', {
    day: '2-digit',
    month: '2-digit',
    year: 'numeric',
  });

  const current = getStoredTickets();
  const updated = current.map((t) => {
    if (t.idOrden !== idOrden) return t;
    return {
      ...t,
      ...updates,
      fechaEntregada: isDelivered
        ? (updates.fechaEntregada || t.fechaEntregada || nowDate)
        : (updates.fechaEntregada !== undefined ? updates.fechaEntregada : t.fechaEntregada),
      esEstadoCambiadoReciente: updates.estado ? true : t.esEstadoCambiadoReciente,
      esEntregadoReciente: isDelivered ? true : t.esEntregadoReciente,
    };
  });
  saveTickets(updated);

  if (typeof window !== 'undefined') {
    const updatedTicket = updated.find((t) => t.idOrden === idOrden);
    if (updatedTicket) {
      fetch('/api/db', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ action: 'ADD_RECEPCION_TICKET', ticket: updatedTicket }),
      }).catch((err) => console.error('[MySQL Error Update Ticket Details]', err));
    }
  }

  return updated;
}

export function updateTicketStatus(idOrden: string, newStatus: string): RecepcionTicket[] {
  const isDelivered = newStatus.trim().toLowerCase() === 'entregada';
  recordStoredId(ESTADOS_CAMBIADOS_STORAGE_KEY, idOrden);
  if (isDelivered) {
    recordStoredId(ENTREGADOS_RECIENTES_STORAGE_KEY, idOrden);
  }

  const nowDate = new Date().toLocaleDateString('es-PY', {
    day: '2-digit',
    month: '2-digit',
    year: 'numeric',
  });

  const current = getStoredTickets();
  const updated = current.map((t) =>
    t.idOrden === idOrden
      ? {
          ...t,
          estado: newStatus,
          fechaEntregada: isDelivered ? t.fechaEntregada || nowDate : t.fechaEntregada,
          esEstadoCambiadoReciente: true,
          esEntregadoReciente: isDelivered ? true : t.esEntregadoReciente,
        }
      : t
  );
  saveTickets(updated);

  if (typeof window !== 'undefined') {
    fetch('/api/db', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ action: 'UPDATE_RECEPCION_STATUS', idOrden, newStatus }),
    }).catch((err) => console.error('[MySQL Error Update Ticket Status]', err));
  }

  return updated;
}

export function resetTickets(): RecepcionTicket[] {
  if (typeof window !== 'undefined') {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(INITIAL_RECEPCION_DATA));
    localStorage.removeItem(NEW_INGRESOS_STORAGE_KEY);
    localStorage.removeItem(ESTADOS_CAMBIADOS_STORAGE_KEY);
    localStorage.removeItem(ENTREGADOS_RECIENTES_STORAGE_KEY);
    fetch('/api/db', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ action: 'RESET_RECEPCION' }),
    }).catch((err) => console.error('[MySQL Error Reset Tickets]', err));
  }
  return INITIAL_RECEPCION_DATA;
}


export interface CambioEstadoCSV {
  idOrden: string;
  cliente: string;
  equipo: string;
  estadoAnterior: string;
  estadoNuevo: string;
  fechaEntregada?: string;
}

export interface ResultadoCargaCSV {
  updatedTickets: RecepcionTicket[];
  totalFilasLeidas: number;
  totalActualizadas: number;
  totalNuevas: number;
  totalSinCambios: number;
  cambios: CambioEstadoCSV[];
  nuevasOrdenesTickets?: RecepcionTicket[];
  changedOrNewTickets?: RecepcionTicket[];
}

/**
 * Parser CSV robusto que soporta delimitadores ',' o ';', comillas dobles y saltos de línea dentro de celdas.
 */
function parseCSVText(csvText: string): string[][] {
  const cleanText = csvText.replace(/^\uFEFF/, '');
  const firstLineEnd = cleanText.indexOf('\n');
  const firstLine = firstLineEnd !== -1 ? cleanText.slice(0, firstLineEnd) : cleanText;
  const semicolonCount = (firstLine.match(/;/g) || []).length;
  const commaCount = (firstLine.match(/,/g) || []).length;
  const tabCount = (firstLine.match(/\t/g) || []).length;

  let delimiter = ',';
  if (semicolonCount > commaCount && semicolonCount > tabCount) {
    delimiter = ';';
  } else if (tabCount > commaCount && tabCount > semicolonCount) {
    delimiter = '\t';
  }

  const rows: string[][] = [];
  let currentRow: string[] = [];
  let currentCell = '';
  let inQuotes = false;

  for (let i = 0; i < cleanText.length; i++) {
    const char = cleanText[i];
    const nextChar = cleanText[i + 1];

    if (inQuotes) {
      if (char === '"' && nextChar === '"') {
        currentCell += '"';
        i++;
      } else if (char === '"') {
        inQuotes = false;
      } else {
        currentCell += char;
      }
    } else {
      if (char === '"') {
        inQuotes = true;
      } else if (char === delimiter) {
        currentRow.push(currentCell.trim());
        currentCell = '';
      } else if (char === '\r' && nextChar === '\n') {
        currentRow.push(currentCell.trim());
        if (currentRow.some((c) => c !== '')) {
          rows.push(currentRow);
        }
        currentRow = [];
        currentCell = '';
        i++;
      } else if (char === '\n' || char === '\r') {
        currentRow.push(currentCell.trim());
        if (currentRow.some((c) => c !== '')) {
          rows.push(currentRow);
        }
        currentRow = [];
        currentCell = '';
      } else {
        currentCell += char;
      }
    }
  }

  if (currentCell !== '' || currentRow.length > 0) {
    currentRow.push(currentCell.trim());
    if (currentRow.some((c) => c !== '')) {
      rows.push(currentRow);
    }
  }

  return rows;
}

function normalizeHeader(h: string): string {
  return h
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/[^a-z0-9]/g, '');
}

function isValidDateCell(str?: string): boolean {
  if (!str) return false;
  const t = str.trim();
  return (
    /^\d{1,2}\/\d{1,2}\/\d{2,4}/.test(t) ||
    /^\d{4}[-/]\d{1,2}[-/]\d{1,2}/.test(t) ||
    /^\d{1,2}[-.]\d{1,2}[-.]\d{2,4}/.test(t)
  );
}

function pickBestDateCell(
  row: string[],
  idxPrimary: number,
  idxFallback: number,
  allowPositionalFallback: boolean,
  positionalIdx: number
): string | undefined {
  const primary = idxPrimary !== -1 ? (row[idxPrimary] || '').trim() : '';
  const fallback = idxFallback !== -1 ? (row[idxFallback] || '').trim() : '';
  if (isValidDateCell(primary)) return primary;
  if (isValidDateCell(fallback)) return fallback;
  if (allowPositionalFallback && row[positionalIdx]) {
    const pos = row[positionalIdx].trim();
    if (pos) return pos;
  }
  return primary || undefined;
}

/**
 * Procesa un archivo CSV de Recepción SATI, compara cada orden con el estado actual del dashboard,
 * actualiza automáticamente los estados que hayan cambiado y devuelve el resumen completo.
 */
export function procesarActualizacionCSV(
  csvText: string,
  currentTickets?: RecepcionTicket[],
  options?: { skipBackgroundSync?: boolean }
): ResultadoCargaCSV {
  const baseTickets = currentTickets ? [...currentTickets] : [...getStoredTickets()];
  const rows = parseCSVText(csvText);

  if (rows.length === 0) {
    return {
      updatedTickets: baseTickets,
      totalFilasLeidas: 0,
      totalActualizadas: 0,
      totalNuevas: 0,
      totalSinCambios: 0,
      cambios: [],
      nuevasOrdenesTickets: [],
      changedOrNewTickets: [],
    };
  }

  let headerRowIdx = -1;
  let idxIdOrden = -1;
  let idxEstado = -1;
  let idxCliente = -1;
  let idxFechaIngreso = -1;
  let idxFechaEntregada = -1;
  let idxFechaTransportadora = -1;
  let idxFechaVenta = -1;
  let idxTipoComponente = -1;
  let idxMarca = -1;
  let idxModelo = -1;
  let idxSerial = -1;
  let idxCodigo = -1;
  let idxMensaje = -1;

  const maxHeaderScan = Math.min(rows.length, 6);
  for (let scan = 0; scan < maxHeaderScan; scan++) {
    const candidateHeaders = rows[scan].map(normalizeHeader);
    const candId = candidateHeaders.findIndex((h) =>
      ['idorden', 'orden', 'nroorden', 'norden', 'id', 'ticket', 'nrodeorden'].includes(h) || h.includes('idorden')
    );
    const candEstado = candidateHeaders.findIndex((h) =>
      ['estado', 'status', 'estadosati', 'situacion'].includes(h) || h.includes('estado')
    );
    const candCliente = candidateHeaders.findIndex((h) =>
      ['cliente', 'nombrecliente', 'usuario', 'titular'].includes(h) || h.includes('cliente')
    );
    const candIngreso = candidateHeaders.findIndex((h) =>
      ['fechaingreso', 'fechadeingreso', 'ingreso', 'fecharecepcion', 'fechaentrada'].includes(h) || h.includes('fechaingreso')
    );
    const candTransport = candidateHeaders.findIndex((h) =>
      h.includes('fechatransport') ||
      h.includes('ftransport') ||
      h.includes('despachotransp') ||
      h === 'transportadora' ||
      h.includes('enviotransp')
    );
    const candEntregada = candidateHeaders.findIndex((h) =>
      !h.includes('transport') &&
      (['fechaentregada', 'fechaentrega', 'fechadeentrega', 'fentrega', 'entregada', 'entregado', 'despacho', 'fechadespacho', 'fechasalida', 'fechaenvio', 'fecharetiro'].includes(h) ||
        h.includes('fechaentreg') ||
        h.includes('fechadeentreg'))
    );
    const candVenta = candidateHeaders.findIndex((h) =>
      ['fechaventa', 'fechadeventa', 'venta', 'fechafactura'].includes(h) || h.includes('fechaventa')
    );
    const candTipo = candidateHeaders.findIndex((h) =>
      ['tipocomponente', 'componente', 'categoria', 'tipo', 'producto'].includes(h) || h.includes('componente')
    );
    const candMarca = candidateHeaders.findIndex((h) => h === 'marca' || h === 'brand' || h.includes('marca'));
    const candModelo = candidateHeaders.findIndex((h) => h === 'modelo' || h === 'model' || h === 'descripcion' || h.includes('modelo'));
    const candSerial = candidateHeaders.findIndex((h) =>
      ['serial', 'serie', 'nroserie', 'sn', 'numeroserie'].includes(h) || h.includes('serial')
    );
    const candCodigo = candidateHeaders.findIndex((h) =>
      ['codigoproducto', 'codigo', 'sku', 'codproducto', 'cod'].includes(h) || h.includes('codigo')
    );
    const candMensaje = candidateHeaders.findIndex((h) =>
      ['mensaje', 'observaciones', 'observacion', 'detalle', 'nota', 'dictamen', 'falla'].includes(h) || h.includes('mensaje')
    );

    const firstIdCell = (rows[scan][candId !== -1 ? candId : 0] || '').replace(/^#/, '').trim();
    const isOrderNumber = /^\d+$/.test(firstIdCell);
    const matches = [candId, candEstado, candCliente, candIngreso, candEntregada, candTransport, candCodigo, candMensaje].filter(
      (i) => i !== -1
    ).length;

    if (!isOrderNumber && matches >= 2) {
      headerRowIdx = scan;
      idxIdOrden = candId;
      idxEstado = candEstado;
      idxCliente = candCliente;
      idxFechaIngreso = candIngreso;
      idxFechaEntregada = candEntregada !== -1 ? candEntregada : candTransport;
      idxFechaTransportadora = candTransport;
      idxFechaVenta = candVenta;
      idxTipoComponente = candTipo;
      idxMarca = candMarca;
      idxModelo = candModelo;
      idxSerial = candSerial;
      idxCodigo = candCodigo;
      idxMensaje = candMensaje;
      break;
    }
  }

  const hasExplicitHeader = headerRowIdx !== -1;
  const startRowIndex = hasExplicitHeader ? headerRowIdx + 1 : 0;

  if (rows.length <= startRowIndex) {
    return {
      updatedTickets: baseTickets,
      totalFilasLeidas: 0,
      totalActualizadas: 0,
      totalNuevas: 0,
      totalSinCambios: 0,
      cambios: [],
      nuevasOrdenesTickets: [],
      changedOrNewTickets: [],
    };
  }

  // Fallback exacto al formato SATI de 12 columnas cuando falta cabecera
  const sampleRowLen = rows[startRowIndex]?.length || rows[0].length;
  const isSati12Cols = !hasExplicitHeader && sampleRowLen >= 8;
  const effectiveIdxId = idxIdOrden !== -1 ? idxIdOrden : 0;
  const effectiveIdxEstado =
    idxEstado !== -1
      ? idxEstado
      : isSati12Cols
        ? 7
        : sampleRowLen >= 6
          ? 5
          : 1;

  // Mapa rápido por idOrden
  const ticketMap = new Map<string, number>();
  baseTickets.forEach((t, index) => {
    ticketMap.set(String(t.idOrden).trim(), index);
  });

  const cambios: CambioEstadoCSV[] = [];
  const nuevasOrdenes: RecepcionTicket[] = [];
  const changedOrNewMap = new Map<string, RecepcionTicket>();
  let totalFilasLeidas = 0;
  let totalSinCambios = 0;

  for (let r = startRowIndex; r < rows.length; r++) {
    const row = rows[r];
    const rawId = (row[effectiveIdxId] || '').replace(/^#/, '').trim();
    const rawNuevoEstado = (row[effectiveIdxEstado] || '').trim() || (isSati12Cols ? 'En Asignacion' : '');

    if (!rawId || !rawNuevoEstado) continue;
    // Órdenes >= 100000 pertenecen a Casa Matriz CDE, no a Sucursal ASU
    if (/^\d+$/.test(rawId) && parseInt(rawId, 10) >= 100000) continue;
    totalFilasLeidas++;

    const existingIndex = ticketMap.get(rawId);

    if (existingIndex !== undefined) {
      const actual = baseTickets[existingIndex];
      const estadoAnterior = (actual.estado || '').trim();
      const fechaEntregadaCSV = pickBestDateCell(
        row,
        idxFechaEntregada,
        idxFechaTransportadora,
        isSati12Cols,
        5
      );
      const mensajeCSV =
        idxMensaje !== -1 && row[idxMensaje]
          ? row[idxMensaje].trim()
          : isSati12Cols && row[3]
            ? row[3].trim()
            : undefined;

      // Comprobar si el estado cambió (comparación insensible a mayúsculas/minúsculas o cambio real de estado)
      const cambioEstado =
        estadoAnterior.toLowerCase() !== rawNuevoEstado.toLowerCase();

      if (cambioEstado) {
        const isDelivered = rawNuevoEstado.toLowerCase().includes('entregada');
        recordStoredId(ESTADOS_CAMBIADOS_STORAGE_KEY, rawId);
        if (isDelivered) {
          recordStoredId(ENTREGADOS_RECIENTES_STORAGE_KEY, rawId);
        }

        const updatedTicket: RecepcionTicket = {
          ...actual,
          estado: rawNuevoEstado,
          fechaEntregada: fechaEntregadaCSV || actual.fechaEntregada,
          mensaje: mensajeCSV !== undefined && mensajeCSV !== '' ? mensajeCSV : actual.mensaje,
          esEstadoCambiadoReciente: true,
          esEntregadoReciente: isDelivered ? true : actual.esEntregadoReciente,
        };
        baseTickets[existingIndex] = updatedTicket;
        changedOrNewMap.set(rawId, updatedTicket);

        cambios.push({
          idOrden: rawId,
          cliente: actual.cliente,
          equipo: `${actual.tipoComponente || ''} ${actual.marca || ''} ${actual.modelo || ''}`.trim(),
          estadoAnterior,
          estadoNuevo: rawNuevoEstado,
          fechaEntregada: updatedTicket.fechaEntregada,
        });
      } else {
        // Si no cambió el estado pero sí se completó fechaEntregada o mensaje en el CSV, lo enriquecemos silenciosamente
        if (
          (fechaEntregadaCSV && fechaEntregadaCSV !== actual.fechaEntregada) ||
          (mensajeCSV && mensajeCSV !== actual.mensaje)
        ) {
          const enrichedLocal: RecepcionTicket = {
            ...actual,
            fechaEntregada: fechaEntregadaCSV || actual.fechaEntregada,
            mensaje: mensajeCSV || actual.mensaje,
          };
          baseTickets[existingIndex] = enrichedLocal;
          changedOrNewMap.set(rawId, enrichedLocal);
        }
        totalSinCambios++;
      }
    } else {
      // Orden que NO estaba en Recepción: se carga automáticamente al dashboard y se agrega a MySQL
      const effCodigo =
        idxCodigo !== -1 ? row[idxCodigo] : isSati12Cols ? row[1] : '';
      const effCliente =
        idxCliente !== -1 ? row[idxCliente] : isSati12Cols ? row[2] : !hasExplicitHeader && row.length >= 2 ? row[1] : '';
      const effMensaje =
        idxMensaje !== -1 ? row[idxMensaje] : isSati12Cols ? row[3] : '';
      const effFechaIngreso =
        idxFechaIngreso !== -1 ? row[idxFechaIngreso] : isSati12Cols ? row[4] : !hasExplicitHeader && row.length >= 3 ? row[2] : '';
      const effFechaEntregada = pickBestDateCell(
        row,
        idxFechaEntregada,
        idxFechaTransportadora,
        isSati12Cols || (!hasExplicitHeader && row.length >= 4),
        isSati12Cols ? 5 : 3
      );
      const effFechaVenta =
        idxFechaVenta !== -1 ? row[idxFechaVenta] : isSati12Cols ? row[6] : !hasExplicitHeader && row.length >= 5 ? row[4] : '';
      const effTipoComp =
        idxTipoComponente !== -1 ? row[idxTipoComponente] : isSati12Cols ? row[8] : !hasExplicitHeader && row.length >= 7 ? row[6] : 'GENERAL';
      const effMarca =
        idxMarca !== -1 ? row[idxMarca] : isSati12Cols ? row[9] : !hasExplicitHeader && row.length >= 8 ? row[7] : '';
      const effModelo =
        idxModelo !== -1 ? row[idxModelo] : isSati12Cols ? row[10] : !hasExplicitHeader && row.length >= 9 ? row[8] : '';
      const effSerial =
        idxSerial !== -1 ? row[idxSerial] : isSati12Cols ? row[11] : '';

      const isDelivered = rawNuevoEstado.toLowerCase().includes('entregada');
      recordStoredId(NEW_INGRESOS_STORAGE_KEY, rawId);
      if (isDelivered) {
        recordStoredId(ENTREGADOS_RECIENTES_STORAGE_KEY, rawId);
      }

      const nuevoTicket: RecepcionTicket = {
        idOrden: rawId,
        codigoProducto: (effCodigo || '').trim(),
        cliente: (effCliente || 'Cliente SATI').trim(),
        mensaje: (effMensaje || '').trim(),
        fechaIngreso: (effFechaIngreso || new Date().toLocaleDateString('es-PY')).trim(),
        fechaEntregada: effFechaEntregada ? effFechaEntregada.trim() : undefined,
        fechaVenta: effFechaVenta ? effFechaVenta.trim() : undefined,
        estado: rawNuevoEstado,
        tipoComponente: (effTipoComp || 'GENERAL').trim(),
        marca: (effMarca || '').trim(),
        modelo: (effModelo || '').trim(),
        serial: effSerial && effSerial.trim() ? effSerial.trim() : 'SIN SERIAL VISIBLE',
        esNuevoIngreso: true,
        esEntregadoReciente: isDelivered,
      };

      nuevasOrdenes.push(nuevoTicket);
      changedOrNewMap.set(rawId, nuevoTicket);
      ticketMap.set(rawId, baseTickets.length + nuevasOrdenes.length - 1);

      cambios.push({
        idOrden: rawId,
        cliente: nuevoTicket.cliente,
        equipo: `${nuevoTicket.tipoComponente} ${nuevoTicket.marca} ${nuevoTicket.modelo}`.trim(),
        estadoAnterior: 'NO ESTABA EN RECEPCIÓN (NUEVA)',
        estadoNuevo: rawNuevoEstado,
        fechaEntregada: nuevoTicket.fechaEntregada,
      });
    }
  }

  const finalTickets =
    nuevasOrdenes.length > 0 ? [...nuevasOrdenes, ...baseTickets] : baseTickets;
  const changedOrNewTickets = Array.from(changedOrNewMap.values());

  if (cambios.length > 0 || nuevasOrdenes.length > 0 || changedOrNewTickets.length > 0) {
    saveTickets(finalTickets);

    // Sincronizar también el espejo local de taller_reparaciones para que el Visor MySQL y Taller reflejen las nuevas órdenes y estados
    if (typeof window !== 'undefined') {
      try {
        const TALLER_KEY = 'nissei_taller_reparaciones_v7_clean';
        const rawTaller = localStorage.getItem(TALLER_KEY);
        if (rawTaller) {
          const tallerList = JSON.parse(rawTaller);
          if (Array.isArray(tallerList)) {
            const tallerMap = new Map<string, number>();
            tallerList.forEach((item: any, idx: number) => {
              tallerMap.set(String(item.idOrden).trim(), idx);
            });

            // 1. Actualizar estados de órdenes existentes en taller
            for (const c of cambios) {
              const tIdx = tallerMap.get(c.idOrden);
              if (tIdx !== undefined) {
                const estLow = c.estadoNuevo.toLowerCase();
                if (estLow.includes('reparada') || estLow === 'entregada' || estLow === 'qc') {
                  tallerList[tIdx] = {
                    ...tallerList[tIdx],
                    estado: 'FINALIZADA',
                    fechaFinalizacion:
                      c.fechaEntregada ||
                      tallerList[tIdx].fechaFinalizacion ||
                      new Date().toLocaleDateString('es-PY'),
                    dictamenFinal: tallerList[tIdx].dictamenFinal || 'REPARADO',
                  };
                } else if (estLow.includes('reparación') || estLow === 'asignada') {
                  if (tallerList[tIdx].estado === 'SIN_ASIGNAR') {
                    tallerList[tIdx] = {
                      ...tallerList[tIdx],
                      estado: 'EN_REPARACION',
                    };
                  }
                }
              }
            }

            // 2. Insertar nuevas órdenes del CSV que correspondan a Taller
            for (const nt of nuevasOrdenes) {
              if (!tallerMap.has(nt.idOrden)) {
                const estLow = nt.estado.toLowerCase();
                if (
                  estLow.includes('reparación') ||
                  estLow.includes('asignad') ||
                  estLow.includes('asignacion') ||
                  estLow.includes('repuesto') ||
                  estLow === 'qc' ||
                  estLow.includes('reparada')
                ) {
                  const esFin = estLow.includes('reparada') || estLow === 'qc';
                  tallerList.unshift({
                    idOrden: nt.idOrden,
                    codigoProducto: nt.codigoProducto || '',
                    cliente: nt.cliente,
                    equipo: `${nt.marca || ''} ${nt.modelo || ''}`.trim() || nt.tipoComponente,
                    marca: nt.marca || '',
                    modelo: nt.modelo || '',
                    tipoComponente: nt.tipoComponente || 'GENERAL',
                    serial: nt.serial || 'SIN SERIAL VISIBLE',
                    fallaReportada: '',
                    detalleReparacion: esFin ? nt.mensaje || '' : '',
                    observaciones: !esFin ? nt.mensaje || '' : '',
                    mensajeSATI: nt.mensaje || '',
                    fechaIngreso: nt.fechaIngreso || '',
                    fechaFinalizacion: esFin ? nt.fechaEntregada || nt.fechaIngreso : undefined,
                    estado: esFin ? 'FINALIZADA' : 'SIN_ASIGNAR',
                    dictamenFinal: esFin ? 'REPARADO' : undefined,
                  });
                }
              }
            }

            localStorage.setItem(TALLER_KEY, JSON.stringify(tallerList));
          }
        }
      } catch (e) {
        console.warn('Error sincronizando caché de taller con CSV:', e);
      }

      if (!options?.skipBackgroundSync) {
        fetch('/api/db', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({
            action: 'BULK_UPDATE_RECEPCION_CSV',
            tickets: changedOrNewTickets,
            cambios: cambios.filter((c) => c.estadoAnterior !== 'NO ESTABA EN RECEPCIÓN (NUEVA)'),
            nuevasOrdenes,
          }),
        }).catch((err) => console.error('[MySQL Error Bulk CSV Update]', err));
      }
    }
  }

  return {
    updatedTickets: finalTickets,
    totalFilasLeidas,
    totalActualizadas: cambios.length - nuevasOrdenes.length,
    totalNuevas: nuevasOrdenes.length,
    totalSinCambios,
    cambios,
    nuevasOrdenesTickets: nuevasOrdenes,
    changedOrNewTickets,
  };
}

/**
 * Sube y sincroniza obligatoriamente el CSV en la base de datos MySQL en la nube (Railway).
 * Espera la confirmación del servidor para garantizar que todos los usuarios vean exactamente
 * los mismos datos sin depender de estados locales divergentes.
 */
export async function sincronizarRecepcionCsvOnline(
  csvText: string,
  currentTickets?: RecepcionTicket[]
): Promise<ResultadoCargaCSV> {
  let cloudBase = currentTickets && currentTickets.length > 0 ? currentTickets : getStoredTickets();

  if (typeof window !== 'undefined') {
    cloudBase = await fetchTicketsFromMySQL({ throwOnError: true });
  }

  const resCalculo = procesarActualizacionCSV(csvText, cloudBase, {
    skipBackgroundSync: true,
  });

  if (resCalculo.totalFilasLeidas === 0) {
    throw new Error(
      'No se detectaron órdenes válidas en el archivo CSV. Verifique el formato SATI exportado.'
    );
  }

  if (typeof window !== 'undefined') {
    const ticketsToPersist =
      resCalculo.changedOrNewTickets && resCalculo.changedOrNewTickets.length > 0
        ? resCalculo.changedOrNewTickets
        : [];
    const cambiosList = resCalculo.cambios.filter(
      (c) => c.estadoAnterior !== 'NO ESTABA EN RECEPCIÓN (NUEVA)'
    );
    const nuevasList = resCalculo.nuevasOrdenesTickets || [];

    if (ticketsToPersist.length > 0 || cambiosList.length > 0 || nuevasList.length > 0) {
      const resp = await fetch('/api/db', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          action: 'BULK_UPDATE_RECEPCION_CSV',
          tickets: ticketsToPersist,
          cambios: cambiosList,
          nuevasOrdenes: nuevasList,
        }),
      });

      const json = await resp.json().catch(() => null);
      if (!resp.ok || !json?.ok) {
        throw new Error(
          json?.error || 'No se pudo sincronizar el CSV en la base de datos MySQL en la nube.'
        );
      }

      if (Array.isArray(json.data) && json.data.length > 0) {
        const enriched = applyCloudRecepcionTickets(json.data as RecepcionTicket[]);
        return {
          ...resCalculo,
          updatedTickets: enriched,
        };
      }
    }
  }

  return resCalculo;
}
